+    private static Date parseMzTime(String value, Date dflt) throws SAXException {
+        if (value == null) {
+            return dflt;
+        }
+        try {
+            return MZ_TIME.parse(value);
+        } catch (ParseException e) {
+            throw new SAXException("invalid metazone time: " + value, e);
+        }
+    }
